.compass{position:absolute;top:29px;left:50%;transform:translateX(-50%);width:105px;height:22px;display:flex;justify-content:space-between;align-items:center;color:#fff9;font:600 8px Outfit;letter-spacing:1px}.compass-n{color:#fff}.compass-line{position:absolute;left:50%;height:8px;width:1px;background:#e5e9d8;top:8px}.compass-tick{position:absolute;left:50%;top:0;width:1px;height:5px;background:#ffffff7c}.compass-e{position:absolute;right:4px;top:6px}.compass-w{position:absolute;left:4px;top:6px}.compass-s{position:absolute;left:50%;bottom:-8px;transform:translateX(-50%);font-size:7px}
