// --- WORLD AND PROPS ---
function makeTree(x,z,type='forest',collectible=false){const y=heightAt(x,z),g=new THREE.Group();g.position.set(x,y,z);scene.add(g);let trunk;if(type==='palm'){trunk=addMesh(new THREE.CylinderGeometry(.24,.38,5.1,7),mats.trunk,g,[0,2.4,0]);trunk.rotation.z=rand(-.16,.16);for(let i=0;i<7;i++){const leaf=addMesh(new THREE.ConeGeometry(.22,4.2,5),mats.palm,g,[Math.sin(i*Math.PI/3.5)*1.5,5.05,Math.cos(i*Math.PI/3.5)*1.5]);leaf.rotation.z=Math.cos(i*Math.PI/3.5)*1.17;leaf.rotation.x=Math.sin(i*Math.PI/3.5)*1.17}for(let i=0;i<3;i++){const c=addMesh(new THREE.SphereGeometry(.35,8,7),mats.fruit,g,[Math.cos(i*2.1)*.48,4.55,Math.sin(i*2.1)*.48]);c.scale.set(.85,1.1,.85)}}else{const h=rand(5.5,9);trunk=addMesh(new THREE.CylinderGeometry(.22,.55,h,7),mats.trunk,g,[0,h/2,0]);const leafmat=Math.random()<.35?mats.leaf2:mats.leaf;for(let i=0;i<4;i++){const crown=addMesh(new THREE.IcosahedronGeometry(rand(1.7,2.6),1),leafmat,g,[rand(-.9,.9),h*.63+i*.7,rand(-.8,.8)]);crown.scale.set(1,rand(.78,1.15),1)}}const radius=type==='palm'?1.0:.82;obstacles.push({x,z,r:radius,tree:true});if(collectible)interactables.push({kind:'tree',name:type==='palm'?'Palm tree':'Tropical tree',x,z,obj:g,hp:3,maxHp:3,alive:true});return g}
function makeRock(x,z,collectible=false,kind='Stone'){const y=heightAt(x,z),g=new THREE.Group();g.position.set(x,y,z);scene.add(g);const rock=addMesh(new THREE.IcosahedronGeometry(rand(.55,1.15),1),mats.rock,g,[0,.45,0]);rock.scale.set(rand(.8,1.4),rand(.7,1.2),rand(.8,1.3));obstacles.push({x,z,r:.9});if(collectible)interactables.push({kind:'resource',name:kind,x,z,obj:g,resource:kind,amount:kind==='Stone'?1:1,alive:true});return g}
function makePickup(x,z,name,emoji){const y=heightAt(x,z),g=new THREE.Group();g.position.set(x,y,z);scene.add(g);if(name==='Branch'){const stick=addMesh(new THREE.CylinderGeometry(.075,.12,.95,6),mats.wood,g,[0,.28,0]);stick.rotation.z=.38}else if(name==='Coconut'){const c=addMesh(new THREE.SphereGeometry(.39,10,8),mats.fruit,g,[0,.38,0]);c.scale.set(1,.83,1)}else if(name==='Fiber'){for(let i=0;i<3;i++){const leaf=addMesh(new THREE.ConeGeometry(.12,.85,5),mats.leaf2,g,[rand(-.2,.2),.4,rand(-.2,.2)]);leaf.rotation.z=rand(-.6,.6)}}else{addMesh(new THREE.IcosahedronGeometry(.28,0),mats.rock,g,[0,.23,0])}interactables.push({kind:'resource',name,x,z,obj:g,resource:name,amount:1,alive:true});return g}
function makeMountain(x,z,r,h){const y=heightAt(x,z)-h*.28;const rock=addMesh(new THREE.ConeGeometry(r,h,7,2),mat(0x747c72),scene,[x,y+h*.32,z]);rock.rotation.y=rand(0,6);rock.scale.z=rand(.72,1.15);rock.castShadow=true}
function makeWreck(){const g=new THREE.Group();g.position.set(-11,heightAt(-11,88)+.05,87);g.rotation.y=-.45;scene.add(g);const fus=addMesh(new THREE.CylinderGeometry(1.2,1.3,15,12,1,true),mat(0x68706d,.6,{metalness:.4}),g,[0,1.7,0]);fus.rotation.z=Math.PI/2;const nose=addMesh(new THREE.ConeGeometry(1.2,2.2,12),mat(0x7f8882,.5,{metalness:.35}),g,[-8.3,1.7,0]);nose.rotation.z=-Math.PI/2;const wing=addMesh(new THREE.BoxGeometry(3.2,.22,13),mat(0x737b73,.55,{metalness:.35}),g,[-1.3,1.6,2]);wing.rotation.z=.12;for(let i=0;i<5;i++){const seat=addMesh(new THREE.BoxGeometry(.8,1.2,.75),mat(0x55574d),g,[rand(-5,5),.9,rand(-.7,.7)]);seat.rotation.y=rand(-.4,.4)}const debris=addMesh(new THREE.BoxGeometry(2,.18,2.7),mat(0x686f69,.6,{metalness:.4}),g,[7,.2,4]);debris.rotation.set(.3,.4,.7);for(let i=0;i<3;i++)makePickup(-12+i*2,83+rand(-2,2),'Branch','🪵');makePickup(-4,92,'Coconut','🥥')}
function makeWorld(){makeTerrain();
  // mountain spine anchors the island's northern skyline.
  [[-36,-55,19,32],[-8,-67,22,40],[23,-57,20,34],[49,-43,17,27],[-52,-23,14,22]].forEach(v=>makeMountain(...v));
  // Tropical palm-fringed crash beach, then a lush, irregular forest interior.
  for(let i=0;i<25;i++){const a=i/25*Math.PI*2,r=96+rand(-5,6);makeTree(Math.cos(a)*r,Math.sin(a)*r,'palm',false)}
  let placed=0,tries=0;while(placed<190&&tries++<1800){const x=rand(-88,88),z=rand(-91,71),r=Math.hypot(x,z);if(r>87||r<16||Math.hypot(x, z-88)<18||heightAt(x,z)<2)continue;if(Math.random()<.14){makeRock(x,z,false);continue}makeTree(x,z,z<-55?'pine':'forest',Math.random()<.34);placed++}
  // Starting resources are sparse and easy to spot.
  [[4,84,'Branch'],[7,90,'Branch'],[-5,79,'Stone'],[7,77,'Stone'],[2,96,'Coconut'],[-9,97,'Coconut'],[12,75,'Fiber'],[-13,72,'Fiber']].forEach(([x,z,n])=>makePickup(x,z,n,n));
  for(let i=0;i<47;i++){const a=rand(0,Math.PI*2),r=rand(26,86),x=Math.cos(a)*r,z=Math.sin(a)*r;if(heightAt(x,z)>2)makeRock(x,z,Math.random()<.18)}
  makeWreck();
  // Freshwater pool and creek in the forest; water is a functional refill source.
  const lake=addMesh(new THREE.CircleGeometry(8,40),mat(0x55999a,.23,{transparent:true,opacity:.85}),scene,[42,heightAt(42,-3)+.04,-3]);lake.rotation.x=-Math.PI/2;interactables.push({kind:'water',name:'Freshwater pool',x:42,z:-3,obj:lake,alive:true});
  for(let i=0;i<4;i++){const x=rand(-58,58),z=rand(-55,45);if(heightAt(x,z)>2)makeAnimal(Math.random()<.72?'deer':'wolf',x,z)}
}
function makeAnimal(kind,x,z){const g=new THREE.Group();g.position.set(x,heightAt(x,z),z);scene.add(g);const fur=mat(kind==='wolf'?0x77796c:0x9a7957),dark=mat(0x352f28);addMesh(new THREE.BoxGeometry(1.3,.75,.6),fur,g,[0,.78,0]);addMesh(new THREE.SphereGeometry(.36,8,7),fur,g,[.68,1.03,0]);for(let s of [-1,1]){addMesh(new THREE.ConeGeometry(.12,.35,5),dark,g,[.77,1.36,s*.16]);for(let lx of [-.4,.4])addMesh(new THREE.CylinderGeometry(.09,.12,.55,6),dark,g,[lx,.32,s*.22])}animals.push({kind,group:g,x,z,phase:rand(0,6),speed:kind==='wolf'?1.1:.8});}

