function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');state.toastClock=2.3}
function message(msg){const el=document.querySelector('#center-message');document.querySelector('#message-text').textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2100)}
function totalWeight(){return Object.entries(state.inventory).reduce((n,[k,v])=>n+v*({Wood:1.2,Branch:.25,Stone:.8,Coconut:.55,Fiber:.12,'Stone Axe':1.8,'Campfire':2,'Basic Shelter':8}[k]||.3),0)}
function addItem(name,n=1){if(totalWeight()+n*({Wood:1.2,Branch:.25,Stone:.8,Coconut:.55,Fiber:.12}[name]||.3)>24){toast('Pack is full — make room first');return false}state.inventory[name]=(state.inventory[name]||0)+n;return true}
function removeItem(name,n=1){if((state.inventory[name]||0)<n)return false;state.inventory[name]-=n;if(!state.inventory[name])delete state.inventory[name];return true}
function closestTarget(){let best=null,bd=4.4;for(const o of interactables){if(!o.alive)continue;const d=dist2(state.position,o);if(d<bd){bd=d;best=o}}for(const b of buildings){if(b.kind==='fire'&&dist2(state.position,b)<3&&bd>3){best=b;bd=dist2(state.position,b)}}return best}
function describeTarget(o){if(o.kind==='tree')return state.equipped==='Stone Axe'?['Chop tree',`${o.name} · ${o.hp}/${o.maxHp} hits`]:['Axe required',`${o.name} · craft a stone axe`];if(o.kind==='resource')return[o.name==='Branch'?'Pick up':o.name==='Coconut'?'Collect':'Gather',`${o.name} · +1`];if(o.kind==='water')return['Drink fresh water','Clear pool · refill thirst'];if(o.kind==='fire')return['Use campfire','Cook · warmth · save point'];if(o.kind==='shelter')return['Take shelter','Rest and save'];return['Interact',o.name||'']}
function interact(){const o=state.near;if(!o){toast('Nothing nearby to interact with');return}if(o.kind==='tree'){if(state.equipped!=='Stone Axe'){toast('You need a stone axe to chop this tree');return}if(state.stamina<8){toast('Too tired to swing — catch your breath');return}state.stamina-=8;o.hp--;state.attack=.45;toast(o.hp>0?`Chop! Tree health ${o.hp}/${o.maxHp}`:'Tree felled · +2 wood');if(o.hp<=0){o.alive=false;scene.remove(o.obj);const ob=obstacles.find(q=>q.x===o.x&&q.z===o.z);if(ob)ob.r=.1;addItem('Wood',2);completeObjective();}return}
if(o.kind==='resource'){if(addItem(o.resource,o.amount||1)){scene.remove(o.obj);o.alive=false;toast(`+1 ${o.resource}`);completeObjective(o.resource)}return}
if(o.kind==='water'){state.thirst=Math.min(100,state.thirst+34);toast('Fresh water · thirst restored');return}
if(o.kind==='fire'){toast('The fire keeps the night at bay');return}if(o.kind==='shelter'){toast('Sheltered from the elements · progress saved');saveGame();return}}
const recipes=[{name:'Stone Axe',icon:'🪓',desc:'A rough-hewn tool for felling trees.',cost:{Branch:2,Stone:2},category:'TOOLS'},{name:'Campfire',icon:'🔥',desc:'A small fire for warmth and cooking.',cost:{Branch:3,Stone:2},category:'SURVIVAL'},{name:'Basic Shelter',icon:'⛺',desc:'A simple lean-to against the rain.',cost:{Wood:5,Branch:3},category:'SURVIVAL'},{name:'Stone Spear',icon:'🔱',desc:'A sturdy first weapon for hunting.',cost:{Branch:2,Stone:1,Fiber:1},category:'TOOLS'}];
function craft(recipe){if(Object.entries(recipe.cost).some(([k,n])=>(state.inventory[k]||0)<n)){toast('Missing materials for '+recipe.name);return}for(const [k,n] of Object.entries(recipe.cost))removeItem(k,n);if(recipe.name==='Stone Axe'){state.inventory[recipe.name]=(state.inventory[recipe.name]||0)+1;state.equipped='Stone Axe';toast('Stone axe crafted and equipped');completeObjective('axe')}else if(recipe.name==='Campfire'||recipe.name==='Basic Shelter'){state.inventory[recipe.name]=(state.inventory[recipe.name]||0)+1;toast(`${recipe.name} crafted · press B to place`)}else{state.inventory[recipe.name]=(state.inventory[recipe.name]||0)+1;toast(`${recipe.name} crafted`)}renderInventory();renderRecipes();saveGame()}

