   for(let i=0;i<20;i++){const slot=document.createElement('button');slot.className='inventory-slot';if(entries[i]){const [name,qty]=entries[i];const icons={Branch:'🪵',Stone:'🪨',Coconut:'🥥',Fiber:'🌿',Wood:'🪵','Stone Axe':'🪓',Campfire:'🔥','Basic Shelter':'⛺','Stone Spear':'🔱'};slot.innerHTML='<span>'+ (icons[name]||'◇')+'</span><span class="slot-name">'+name+'</span><span class="qty">'+qty+'</span>';slot.onclick=()=>useItem(name)}grid.appendChild(slot)}
   const w=totalWeight();document.querySelector('#inventory-weight').textContent=w.toFixed(1)+' / 24 KG';document.querySelector('#weight-label').textContent=w.toFixed(1)+' / 24 kg';document.querySelector('#wood-count').textContent=state.inventory.Wood||0;document.querySelector('#stone-count').textContent=state.inventory.Stone||0;document.querySelector('#equipped-name').textContent=state.equipped?state.equipped.toUpperCase():'EMPTY HANDS';document.querySelector('#equipment-label').textContent=state.equipped||'Nothing equipped'}
 function useItem(name){if(name==='Coconut'){if(removeItem(name)){state.hunger=Math.min(100,state.hunger+16);toast('Coconut eaten · hunger restored');renderInventory()}}else if(name==='Stone Axe'||name==='Stone Spear'){state.equipped=name;toast(name+' equipped');renderInventory()}else if(name==='Campfire'||name==='Basic Shelter'){state.buildMode=name;toast('Move to clear ground, then press B to place');closePanels()}}
 function renderRecipes(){const list=document.querySelector('#recipe-list');if(!list)return;list.innerHTML='';for(const r of recipes){const box=document.createElement('article');box.className='recipe-card';const can=Object.entries(r.cost).every(([k,n])=>(state.inventory[k]||0)>=n);box.innerHTML='<span class="recipe-icon">'+r.icon+'</span><div class="recipe-info"><small>'+r.category+'</small><h3>'+r.name+'</h3><p>'+r.desc+'</p><div class="recipe-cost">'+Object.entries(r.cost).map(([k,n])=>'<span>'+k+' <b>'+ (state.inventory[k]||0)+'/'+n+'</b></span>').join('')+'</div></div><button class="craft-button'+(can?' ready':'')+'">'+(can?'CRAFT':'MISSING')+' <span>→</span></button>';box.querySelector('.craft-button').onclick=()=>craft(r);list.appendChild(box)}}
