+function openPanel(name){if(!name){closePanels();return}closePanels(false);state.panel=name;state.paused=true;const panel=document.querySelector('#'+name+'-panel');if(panel){panel.classList.add('open');document.querySelector('#panel-backdrop').classList.add('open')}else{state.panel=null;state.paused=false}}
 function closePanels(resume=true){document.querySelectorAll('.game-panel').forEach(p=>p.classList.remove('open'));document.querySelector('#panel-backdrop').classList.remove('open');state.panel=null;if(resume)state.paused=false}
 function completeObjective(resource){if(resource==='Branch'||resource==='Stone'||resource==='Coconut'||resource==='Fiber'){if(state.mission===0){if((state.inventory.Branch||0)>=3){document.querySelector('#objective-title').textContent='A sharper edge';document.querySelector('#objective-copy').textContent='Craft a stone axe using 2 branches and 2 stone.';document.querySelector('#objective-fill').style.width='100%';document.querySelector('#objective-progress').textContent='STONE AXE MATERIALS READY'}}}if(resource==='axe'){state.mission=1;document.querySelector('#objective-title').textContent='Claim a little shelter';document.querySelector('#objective-copy').textContent='Chop a tree and gather 5 wood.';document.querySelector('#objective-fill').style.width='33%';document.querySelector('#objective-progress').textContent='0 / 5 WOOD'}if(resource===undefined&&state.mission===1){const wood=state.inventory.Wood||0;document.querySelector('#objective-progress').textContent=Math.min(wood,5)+' / 5 WOOD';document.querySelector('#objective-fill').style.width=(Math.min(wood,5)/5*100)+'%'}}
 function saveGame(){try{localStorage.setItem('wild-survival-save',JSON.stringify({inventory:state.inventory,equipped:state.equipped,mission:state.mission,day:state.day,position:[state.position.x,state.position.z],health:state.health,hunger:state.hunger,thirst:state.thirst}))}catch(e){}}
 function loadGame(){try{const d=JSON.parse(localStorage.getItem('wild-survival-save'));if(!d)return;Object.assign(state.inventory,d.inventory||{});state.equipped=d.equipped||'';state.mission=d.mission||0;state.day=d.day||1;state.health=d.health??100;state.hunger=d.hunger??82;state.thirst=d.thirst??74;if(d.position)state.position.set(d.position[0],0,d.position[1])}catch(e){}}

